mapper.select:
        select
       *
        from wms_scrap
        where bool_delete_enum = 0
        
            and workshop_id = #{workshopId}
        
        
            and warehouse_id = #{warehouseId}
        
        
            and project_id is null
        
        
            and project_id is not null
        
        
            and project_id = #{projectId}
        
        
            and theory_thickness = #{theoryThickness}
        
        
            and thickness = #{thickness}
        
        
            and basic_class & #{ basicClass} > 0
        
        
            and width = #{width}
        
        
            and length = #{length}
        

        -- 长度范围只用于钢卷查询,钢卷quantity计量量记录长度
        
            and quantity >= #{minLength}
        
        
            and quantity <= #{maxLength}
        

        
            and color like CONCAT('%', #{color},'%')
        
        
            and specification like CONCAT('%', #{specification},'%')
        
        
            and heat_no_and_batch_no like CONCAT('%', #{heatNoAndBatchNo},'%')
        
        
            and classify_id in
            
                #{item}
            
        
        
            and classify_id = #{classifyId}
